                // Prepare the JSON object for the request
                var seriesTimerJson = new
                {
                    channel = info.ChannelId,
                    title = info.Name,
                    description = info.Overview,
                    record_any_time = info.RecordAnyTime,
                    record_any_channel = info.RecordAnyChannel,
